AgwHeader::AgwHeader()
{
    msg_type = 0;
    msg_ver = 0;
    reserver = 0;
    seq_num = 0;
    body_length = 0;
}
/*
 * @brief 消息头
 */
size_t AgwHeader::GetSize() const
{
    return ( 0  + 16 );
}
void AgwHeader::DumpAsString(std::ostream& os) const
{
    os << "AgwHeader:" << "<";
    os << "msg_type=" << msg_type << "|";
    os << "msg_ver=" << msg_ver << "|";
    os << "reserver=" << reserver << "|";
    os << "seq_num=" << seq_num << "|";
    os << "body_length=" << body_length << "|";
    os <<">";
}
void AgwHeader::FillDefaultValue()
{
    msg_type = 0;
    msg_ver = 0;
    reserver = 0;
    seq_num = 0;
    body_length = 0;
}
bool AgwHeader::Diff(const AgwHeader& msg)
{
    if (msg_type != msg.msg_type) {return false;}
    if (msg_ver != msg.msg_ver) {return false;}
    if (reserver != msg.reserver) {return false;}
    if (seq_num != msg.seq_num) {return false;}
    if (body_length != msg.body_length) {return false;}
    return true;
}
error_code AgwHeader::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    if ((ec = decoder.PopField(msg_type))){return ec;}
    if ((ec = decoder.PopField(msg_ver))){return ec;}
    if ((ec = decoder.PopField(reserver))){return ec;}
    if ((ec = decoder.PopField(seq_num))){return ec;}
    if ((ec = decoder.PopField(body_length))){return ec;}
    return ec;
}
error_code AgwHeader::Encode(MessageEncoder& encoder) const
{
    error_code ec = mp::kSuccess;
    encoder.PushField(msg_type);
    encoder.PushField(msg_ver);
    encoder.PushField(reserver);
    encoder.PushField(seq_num);
    encoder.PushField(body_length);
    return ec;
}
AgwMsgLogin::AgwMsgLogin()
{
    sender_comp_id.fill(' ');
    target_comp_id.fill(' ');
    heart_bt_int = 0;
    password.fill(' ');
    default_app_ver_id.fill(' ');
    spec_cust_flag = 0;
    trade_pwd = "";
}
/*
 * @brief 登录消息
 */
size_t AgwMsgLogin::GetSize() const
{
    return ( 0          + (4 + trade_pwd.size()) + 133 );
}
void AgwMsgLogin::DumpAsString(std::ostream& os) const
{
    os << "[msg_no:3: ver:0]" << "<";
    os << "AgwMsgLogin:" << "<";
    os << "sender_comp_id=\"" << mp::AsString(sender_comp_id) << "\"|";
    os << "target_comp_id=\"" << mp::AsString(target_comp_id) << "\"|";
    os << "heart_bt_int=" << heart_bt_int << "|";
    os << "password=\"" << mp::AsString(password) << "\"|";
    os << "default_app_ver_id=\"" << mp::AsString(default_app_ver_id) << "\"|";
    os << "spec_cust_flag=" << (unsigned int)spec_cust_flag << "|";
    os << "trade_pwd=\"" << trade_pwd << "\"|";
    os <<">";
}
void AgwMsgLogin::FillDefaultValue()
{
    sender_comp_id.fill(' ');
    target_comp_id.fill(' ');
    heart_bt_int = 0;
    password.fill(' ');
    default_app_ver_id.fill(' ');
    spec_cust_flag = 0;
    trade_pwd = "";
}
bool AgwMsgLogin::Diff(const AgwMsgLogin& msg)
{
    if (sender_comp_id != msg.sender_comp_id) {return false;}
    if (target_comp_id != msg.target_comp_id) {return false;}
    if (heart_bt_int != msg.heart_bt_int) {return false;}
    if (password != msg.password) {return false;}
    if (default_app_ver_id != msg.default_app_ver_id) {return false;}
    if (spec_cust_flag != msg.spec_cust_flag) {return false;}
    if (trade_pwd != msg.trade_pwd) {return false;}
    return true;
}
error_code AgwMsgLogin::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    if ((ec = decoder.PopField(sender_comp_id))){return ec;}
    if ((ec = decoder.PopField(target_comp_id))){return ec;}
    if ((ec = decoder.PopField(heart_bt_int))){return ec;}
    if ((ec = decoder.PopField(password))){return ec;}
    if ((ec = decoder.PopField(default_app_ver_id))){return ec;}
    if ((ec = decoder.PopField(spec_cust_flag))){return ec;}
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
if (embed_num_for_mp > readable_size) {return mp::kFailure;}
if ((ec = decoder.PopField(trade_pwd, embed_num_for_mp))) {return ec;}

    return ec;
}
error_code AgwMsgLogin::Encode(MessageEncoder& encoder) const
{
    error_code ec = mp::kSuccess;
    encoder.PushField(sender_comp_id);
    encoder.PushField(target_comp_id);
    encoder.PushField(heart_bt_int);
    encoder.PushField(password);
    encoder.PushField(default_app_ver_id);
    encoder.PushField(spec_cust_flag);
    encoder.PushField(static_cast<mp::NumInGroup_def>(trade_pwd.size()));
encoder.PushField(trade_pwd);
    return ec;
}
