AgwMsgSync::AgwMsgSync()
{
    for (size_t i = 0; i < no_parition_array.size(); ++i){
            no_parition_array[i].FillDefaultValue();
        }

}
/*
 * @brief 回报同步消息
 */
size_t AgwMsgSync::GetSize() const
{
    return ( 0          + 4 + (mp::GetSequenceSize< std::vector<AgwNoPartitionArray> >(no_parition_array)) + 0 );
}
void AgwMsgSync::DumpAsString(std::ostream& os) const
{
    os << "[msg_no:5: ver:0]" << "<";
    os << "AgwMsgSync:" << "<";
    for (size_t i = 0; i < no_parition_array.size(); ++i){
            no_parition_array[i].DumpAsString(os);
        }

    os <<">";
}
void AgwMsgSync::FillDefaultValue()
{
    for (size_t i = 0; i < no_parition_array.size(); ++i){
            no_parition_array[i].FillDefaultValue();
        }

}
bool AgwMsgSync::Diff(const AgwMsgSync& msg)
{
    for (size_t i = 0; i < no_parition_array.size(); ++i) {
            if (!no_parition_array[i].Diff((AgwNoPartitionArray)(msg.no_parition_array[i]))) {return false;}
        }

    return true;
}
error_code AgwMsgSync::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
        if (embed_num_for_mp > readable_size) {return mp::kFailure;}
        no_parition_array.resize(embed_num_for_mp);
        for (size_t i = 0; i < embed_num_for_mp; ++i){
            if ( (ec = no_parition_array[i].Decode(decoder))) {return ec;}
        }

    return ec;
}
error_code AgwMsgSync::Encode(MessageEncoder& encoder) const
{
    error_code ec = mp::kSuccess;
    encoder.PushField(static_cast<mp::NumInGroup_def>(no_parition_array.size()));
        for (size_t i = 0; i < no_parition_array.size(); ++i){
            if ((ec = no_parition_array[i].Encode(encoder))) {return ec;}
        }

    return ec;
}
