error_code AgwMsgOrderReport::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    if ((ec = decoder.PopField(partition))){return ec;}
    if ((ec = decoder.PopField(index))){return ec;}
    if ((ec = decoder.PopField(business_type))){return ec;}
    if ((ec = decoder.PopField(client_order_no))){return ec;}
    if ((ec = decoder.PopField(security_id))){return ec;}
    if ((ec = decoder.PopField(market_id))){return ec;}
    if ((ec = decoder.PopField(exec_type))){return ec;}
    if ((ec = decoder.PopField(order_status))){return ec;}
    if ((ec = decoder.PopField(cust_id))){return ec;}
    if ((ec = decoder.PopField(fund_account_id))){return ec;}
    if ((ec = decoder.PopField(account_id))){return ec;}
    if ((ec = decoder.PopField(price))){return ec;}
    if ((ec = decoder.PopField(order_qty))){return ec;}
    if ((ec = decoder.PopField(leaves_qty))){return ec;}
    if ((ec = decoder.PopField(cum_qty))){return ec;}
    if ((ec = decoder.PopField(side))){return ec;}
    if ((ec = decoder.PopField(transact_time))){return ec;}
    if ((ec = decoder.PopField(user_info))){return ec;}
    if ((ec = decoder.PopField(order_id))){return ec;}
    if ((ec = decoder.PopField(cl_ord_id))){return ec;}
    if ((ec = decoder.PopField(branch_id))){return ec;}
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
if (embed_num_for_mp > readable_size) {return mp::kFailure;}
if ((ec = decoder.PopField(key_error_msg, embed_num_for_mp))) {return ec;}

    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
if (embed_num_for_mp > readable_size) {return mp::kFailure;}
if ((ec = decoder.PopField(key_error_code, embed_num_for_mp))) {return ec;}

    if ((ec = decoder.PopField(key_error_level))){return ec;}
    return ec;
}
