error_code AgwMsgExtDirectRepay::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    if ((ec = decoder.PopField(time))){return ec;}
    if ((ec = decoder.PopField(cust_id))){return ec;}
    if ((ec = decoder.PopField(fund_account_id))){return ec;}
    if ((ec = decoder.PopField(branch_id))){return ec;}
    if ((ec = decoder.PopField(account_id))){return ec;}
    if ((ec = decoder.PopField(is_account_partition))){return ec;}
    if ((ec = decoder.PopField(currency))){return ec;}
    if ((ec = decoder.PopField(order_way))){return ec;}
    if ((ec = decoder.PopField(repay_value))){return ec;}
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
if (embed_num_for_mp > readable_size) {return mp::kFailure;}
if ((ec = decoder.PopField(remark, embed_num_for_mp))) {return ec;}

    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
if (embed_num_for_mp > readable_size) {return mp::kFailure;}
if ((ec = decoder.PopField(password, embed_num_for_mp))) {return ec;}

    if ((ec = decoder.PopField(client_seq_id))){return ec;}
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
if (embed_num_for_mp > readable_size) {return mp::kFailure;}
if ((ec = decoder.PopField(client_feature_code, embed_num_for_mp))) {return ec;}

    if ((ec = decoder.PopField(user_info))){return ec;}
    if ((ec = decoder.PopField(order_way_ext))){return ec;}
    return ec;
}
