error_code AgwUTEComponentShareFrozenInfo::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    uint32_t len = 0;
    decoder.PopField(len);
    SetMessagelen(len);
    if(len >= 4) ///<4为重复组的前导长度字节
    {
        len -= 4;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(security_id))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 2)
    {
        if ((ec = decoder.PopField(market_id))){return ec;}
        len -= 2;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(frozen_type1))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(frozen_type3))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(frozen_type4))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(frozen_type10))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(frozen_fund))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len > 0)
    {
         std::vector<char> remaining_buf(len);
         decoder.PopField(remaining_buf);
         len -= len;
    }
    return ec;
}
