error_code AgwExtQueryResultTradeCollect::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    if ((ec = AgwMsgExtQueryResultBase::Decode(decoder))){return ec;}
    if ((ec = decoder.PopField(all_buy_avg_price))){return ec;}
    if ((ec = decoder.PopField(all_buy_cum_qty))){return ec;}
    if ((ec = decoder.PopField(all_buy_total_value_traded))){return ec;}
    if ((ec = decoder.PopField(all_sell_avg_price))){return ec;}
    if ((ec = decoder.PopField(all_sell_cum_qty))){return ec;}
    if ((ec = decoder.PopField(all_sell_total_value_traded))){return ec;}
    if ((ec = decoder.PopField(all_total_value_traded))){return ec;}
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
        if (embed_num_for_mp > readable_size) {return mp::kFailure;}
        trade_collect_array.resize(embed_num_for_mp);
        for (size_t i = 0; i < embed_num_for_mp; ++i){
            if ( (ec = trade_collect_array[i].Decode(decoder))) {return ec;}
        }

    return ec;
}
