bool AgwMsgExtQueryResultCustTotalAssets::Diff(const AgwMsgExtQueryResultCustTotalAssets& msg)
{
    if (!AgwMsgExtQueryResultBase::Diff((AgwMsgExtQueryResultBase)msg)) {return false;}
    if (te_partition_no != msg.te_partition_no) {return false;}
    if (status != msg.status) {return false;}
    if (cust_name != msg.cust_name) {return false;}
    if (cust_type != msg.cust_type) {return false;}
    for (size_t i = 0; i < order_array.size(); ++i) {
            if (!order_array[i].Diff((AgwCustTotalAssetsArray)(msg.order_array[i]))) {return false;}
        }

    return true;
}
error_code AgwMsgExtQueryResultCustTotalAssets::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    if ((ec = AgwMsgExtQueryResultBase::Decode(decoder))){return ec;}
    if ((ec = decoder.PopField(te_partition_no))){return ec;}
    if ((ec = decoder.PopField(status))){return ec;}
    if ((ec = decoder.PopField(cust_name))){return ec;}
    if ((ec = decoder.PopField(cust_type))){return ec;}
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
        if (embed_num_for_mp > readable_size) {return mp::kFailure;}
        order_array.resize(embed_num_for_mp);
        for (size_t i = 0; i < embed_num_for_mp; ++i){
            if ( (ec = order_array[i].Decode(decoder))) {return ec;}
        }

    return ec;
}
error_code AgwMsgExtQueryResultCustTotalAssets::Encode(MessageEncoder& encoder) const
{
    error_code ec = mp::kSuccess;
    if ((ec = AgwMsgExtQueryResultBase::Encode(encoder))){return ec;}
    encoder.PushField(te_partition_no);
    encoder.PushField(status);
    encoder.PushField(cust_name);
    encoder.PushField(cust_type);
    encoder.PushField(static_cast<mp::NumInGroup_def>(order_array.size()));
        for (size_t i = 0; i < order_array.size(); ++i){
            if ((ec = order_array[i].Encode(encoder))) {return ec;}
        }

    return ec;
}
