error_code AgwMsgExtQueryResultDDCustInfo::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    if ((ec = AgwMsgExtQueryResultBase::Decode(decoder))){return ec;}
    if ((ec = decoder.PopField(total_num))){return ec;}
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
        if (embed_num_for_mp > readable_size) {return mp::kFailure;}
        order_array.resize(embed_num_for_mp);
        for (size_t i = 0; i < embed_num_for_mp; ++i){
            if ( (ec = order_array[i].Decode(decoder))) {return ec;}
        }

    return ec;
}
