bool AgwMsgExtQueryResultCreditTradeCollect::Diff(const AgwMsgExtQueryResultCreditTradeCollect& msg)
{
    if (!AgwMsgExtQueryResultBase::Diff((AgwMsgExtQueryResultBase)msg)) {return false;}
    if (oper_date != msg.oper_date) {return false;}
    if (last_index != msg.last_index) {return false;}
    if (total_num != msg.total_num) {return false;}
    for (size_t i = 0; i < order_array.size(); ++i) {
            if (!order_array[i].Diff((AgwCreditTradeCollectArray)(msg.order_array[i]))) {return false;}
        }

    return true;
}
error_code AgwMsgExtQueryResultCreditTradeCollect::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    if ((ec = AgwMsgExtQueryResultBase::Decode(decoder))){return ec;}
    if ((ec = decoder.PopField(oper_date))){return ec;}
    if ((ec = decoder.PopField(last_index))){return ec;}
    if ((ec = decoder.PopField(total_num))){return ec;}
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
        if (embed_num_for_mp > readable_size) {return mp::kFailure;}
        order_array.resize(embed_num_for_mp);
        for (size_t i = 0; i < embed_num_for_mp; ++i){
            if ( (ec = order_array[i].Decode(decoder))) {return ec;}
        }

    return ec;
}
error_code AgwMsgExtQueryResultCreditTradeCollect::Encode(MessageEncoder& encoder) const
{
    error_code ec = mp::kSuccess;
    if ((ec = AgwMsgExtQueryResultBase::Encode(encoder))){return ec;}
    encoder.PushField(oper_date);
    encoder.PushField(last_index);
    encoder.PushField(total_num);
    encoder.PushField(static_cast<mp::NumInGroup_def>(order_array.size()));
        for (size_t i = 0; i < order_array.size(); ++i){
            if ((ec = order_array[i].Encode(encoder))) {return ec;}
        }

    return ec;
}
