{
    error_code ec = mp::kSuccess;
    if ((ec = AgwMsgExtQueryResultBase::Encode(encoder))){return ec;}
    encoder.PushField(last_index);
    encoder.PushField(total_num);
    encoder.PushField(static_cast<mp::NumInGroup_def>(order_array.size()));
        for (size_t i = 0; i < order_array.size(); ++i){
            if ((ec = order_array[i].Encode(encoder))) {return ec;}
        }

    return ec;
}
