error_code AgwAcctArray::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    uint32_t len = 0;
    decoder.PopField(len);
    SetMessagelen(len);
    if(len >= 4) ///<4为重复组的前导长度字节
    {
        len -= 4;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 2)
    {
        if ((ec = decoder.PopField(market_id))){return ec;}
        len -= 2;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 4)
    {
        if ((ec = decoder.PopField(currency))){return ec;}
        len -= 4;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 16)
    {
        if ((ec = decoder.PopField(fund_account_id))){return ec;}
        len -= 16;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 12)
    {
        if ((ec = decoder.PopField(account_id))){return ec;}
        len -= 12;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 16)
    {
        if ((ec = decoder.PopField(pt_fund_account_id))){return ec;}
        len -= 16;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 12)
    {
        if ((ec = decoder.PopField(pt_account_id))){return ec;}
        len -= 12;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len > 0)
    {
         std::vector<char> remaining_buf(len);
         decoder.PopField(remaining_buf);
         len -= len;
    }
    return ec;
}
