bool AgwMsgETFRedemptionTradeDealER::Diff(const AgwMsgETFRedemptionTradeDealER& msg)
{
    if (!AgwMsgTradeExecutionReport::Diff((AgwMsgTradeExecutionReport)msg)) {return false;}
    for (size_t i = 0; i < constituent_stock.size(); ++i) {
            if (!constituent_stock[i].Diff((AgwMsgETFConstituentStockUnit)(msg.constituent_stock[i]))) {return false;}
        }

    return true;
}
error_code AgwMsgETFRedemptionTradeDealER::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    if ((ec = AgwMsgTradeExecutionReport::Decode(decoder))){return ec;}
    if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
        if (embed_num_for_mp > readable_size) {return mp::kFailure;}
        constituent_stock.resize(embed_num_for_mp);
        for (size_t i = 0; i < embed_num_for_mp; ++i){
            if ( (ec = constituent_stock[i].Decode(decoder))) {return ec;}
        }

    return ec;
}
error_code AgwMsgETFRedemptionTradeDealER::Encode(MessageEncoder& encoder) const
{
    error_code ec = mp::kSuccess;
    if ((ec = AgwMsgTradeExecutionReport::Encode(encoder))){return ec;}
    encoder.PushField(static_cast<mp::NumInGroup_def>(constituent_stock.size()));
        for (size_t i = 0; i < constituent_stock.size(); ++i){
            if ((ec = constituent_stock[i].Encode(encoder))) {return ec;}
        }

    return ec;
}
