error_code AgwMsgOfferTendererInfo::Decode(MessageDecoder& decoder)
{
    error_code ec = mp::kSuccess;
    mp::NumInGroup_def embed_num_for_mp;
    mp::NumInGroup_def readable_size = static_cast<mp::NumInGroup_def>(decoder.left_bytes());
    uint32_t len = 0;
    decoder.PopField(len);
    SetMessagelen(len);
    if(len >= 4) ///<4为重复组的前导长度字节
    {
        len -= 4;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(security_id))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 2)
    {
        if ((ec = decoder.PopField(market_id))){return ec;}
        len -= 2;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 40)
    {
        if ((ec = decoder.PopField(security_symbol))){return ec;}
        len -= 40;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 6)
    {
        if ((ec = decoder.PopField(tenderer_id))){return ec;}
        len -= 6;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= (4 + tenderer_name.size()))
    {
        if ((ec = decoder.PopField(embed_num_for_mp))){return ec;}
if (embed_num_for_mp > readable_size) {return mp::kFailure;}
if ((ec = decoder.PopField(tenderer_name, embed_num_for_mp))) {return ec;}

        len -= (4 + tenderer_name.size());
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(offering_price))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(start_date))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len >= 8)
    {
        if ((ec = decoder.PopField(end_date))){return ec;}
        len -= 8;
    }
    else
    {
        return mp::kSuccess;
    }
    if(len > 0)
    {
         std::vector<char> remaining_buf(len);
         decoder.PopField(remaining_buf);
         len -= len;
    }
    return ec;
}
